export const WORST_CASES: { scenario: string; response: string }[] = [
  { scenario: "Rain / high wind", response: "No flying. Do ALL ground testing: diagnostics, FOV cal, inference benchmark, live stream test, ground-level CV on dummy, bench_mission.py, dry-run scripts. Productive day even without flight." },
  { scenario: "GPS never locks", response: "Can't fly autonomous. Do manual RC hover (if arming works without GPS — unlikely). Main value: ground-level CV tests, camera calibration, stream test, bench diagnostics. Note GPS issues for next attempt." },
  { scenario: "Cube won't arm", response: "Read pre-arm failure in MP Messages. Fix what you can (compass/accel/RC cal). If unfixable: do ALL ground tests. Pi camera + AI testing doesn't need Cube armed." },
  { scenario: "CV detects nothing at any altitude", response: "STILL VALUABLE. Save all frames (flight_frames/). These real aerial photos become retraining data. Try COCO model, lower confidence to 0.15, bigger dummy. The 'failure' data is exactly what we need to improve for Day 2." },
  { scenario: "Everything works perfectly", response: "Run all 3 tiers. Extra time: repeat altitude test with different models, test at different angles, try cone detection, do multiple landing accuracy measurements, full main.py autonomous mission." },
  { scenario: "Pi overheats / crashes", response: "Let Pi cool 5 min. Remove case if present. Run without stream (--headless only, no --stream). Reduce to camera-only tests. Transfer to bench testing." },
  { scenario: "WiFi range drops mid-flight", response: "Pi continues logging locally regardless of WiFi. If stream freezes: pilot flies by line of sight (mandatory anyway), GS operator checks phone hotspot. Move laptop closer if possible. All data saved on Pi." },
  { scenario: "Dummy blows away in wind", response: "Weight dummy with rocks on corners or stake with tent pegs. Bring spare tape. If it flips: land, re-secure, retry." },
  { scenario: "Disk space fills on Pi", response: "Before flight: run 'df -h' on Pi. Need at least 2GB free. If full: delete old detections/ and flight_frames/ folders. Raw frames at 640x480 ≈ 100KB each, so 1000 frames ≈ 100MB." },
  { scenario: "CSI ribbon cable loosens during transport", response: "Before powering on: open Pi case, check CSI ribbon is seated firmly (lift black clip, push ribbon, press clip). Secure with electrical tape across connection." },
  { scenario: "Phone hotspot battery dies", response: "Keep phone plugged into power bank while hotspotting. Alternatively: Pi can create its own hotspot (sudo nmcli dev wifi hotspot). Or work directly on Pi with HDMI+keyboard." },
];

